function dateStr(d){if(!d)return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function shift(s,n){let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return dateStr(d)}
function readable(s){const d=new Date(s+'T12:00:00');return `${d.getMonth()+1}月${d.getDate()}日（${'日月火水木金土'[d.getDay()]}）`}
function safe(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function attr(s){return safe(s)}
function url(s){try{let u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function fmt(n,d=0){return (Math.round((+n||0)*10**d)/10**d).toLocaleString('ja-JP',{maximumFractionDigits:d})}
function money(n){return n==null?'価格未確認':`¥${fmt(n)}`}
function escapeCsv(s){return '"'+String(s??'').replace(/"/g,'""')+'"'}
const loaded=window.NutriAccount ? await window.NutriAccount.ready : null;const state={page:'today',date:dateStr(),cat:'all',store:'all',genre:'all',storeRowHidden:false,meal:mealByTime(),mealExplicit:false,query:'',sort:'recommended',limit:60,goals:{...DEFAULT_GOALS,...(loaded?.goals||{})},logs:Array.isArray(loaded?.logs)?loaded.logs:[],custom:normCustom(loaded?.custom),extraStores:normStores(loaded?.extraStores),profile:{sex:'unspecified',birth:'',age:'',height:null,weight:null,targetWeight:null,activity:'light',goal:'loss',deficit:350,waist:null,bodyFat:null,alt:null,ast:null,tg:null,hdl:null,ldl:null,glucose:null,hba1c:null,systolic:null,diastolic:null,measuredAt:'',...(loaded?.profile||{})},measurements:Array.isArray(loaded?.measurements)?loaded.measurements:[],autoGoals:loaded?.autoGoals??true,theme:'light'};
function persist(){try{window.NutriAccount.save({goals:state.goals,logs:state.logs,custom:state.custom,extraStores:state.extraStores,profile:state.profile,measurements:state.measurements,autoGoals:state.autoGoals,theme:'light'})}catch{toast('保存に失敗しました。容量またはブラウザ設定を確認してください。')}}
function normStores(list){const out=[];for(const x of Array.isArray(list)?list:[]){const name=String(typeof x==='string'?x:x?.name||'').trim();if(!name||LEGACY_STORE[name]||STORE_DEFS.some(d=>d[0]===name)||out.some(o=>o.name===name))continue;const c0=LEGACY_CAT[x?.cat]||x?.cat;const cat=CATEGORIES.some(c=>c[0]===c0)?c0:'その他';out.push({name,cat})}return out}
function normCustom(list){return (Array.isArray(list)?list:[]).map(f=>LEGACY_STORE[f?.store]?{...f,store:LEGACY_STORE[f.store]}:f)}
function foods(){return [...(window.SEED_FOODS||[]),...state.custom]}
function food(id){return foods().find(x=>x.id===id)}
function stores(){return [...STORE_DEFS.map(d=>d[0]),...state.extraStores.map(x=>x.name)]}
function storeCat(name){name=LEGACY_STORE[name]||name;const d=STORE_DEFS.find(x=>x[0]===name);if(d)return d[1];const e=state.extraStores.find(x=>x.name===name);return e?e.cat:'その他'}
function storesIn(cat){const fromFoods=[...new Set(state.custom.map(f=>f.store))];return [...new Set([...stores(),...fromFoods])].filter(s=>storeCat(s)===cat)}
function usedCategories(){return [...CATEGORIES.filter(([c])=>c!=='自販機'&&(c!=='その他'||storesIn('その他').length)),[DRINK,'◍']]}
function drinkPlaces(){return CATEGORIES.map(c=>c[0]).filter(c=>foods().some(f=>foodKind(f)==='drink'&&(storeCat(f.store)===c||soldInCat(f,c))))}
function soldAt(f,place){return !!f.places&&(f.places.includes(place)||f.places.includes(storeCat(place)))}
function soldInCat(f,cat){return !!f.places&&f.places.some(p=>p===cat||storeCat(p)===cat)}
function currentFilter(){return {cat:state.cat,store:state.store}}
function matchesFilter(f,flt=currentFilter()){if(flt.cat===DRINK)return foodKind(f)==='drink'&&(flt.store==='all'||storeCat(f.store)===flt.store||soldInCat(f,flt.store));if(f.places&&flt.cat!=='all')return flt.store!=='all'?soldAt(f,flt.store):soldInCat(f,flt.cat);return (flt.cat==='all'||storeCat(f.store)===flt.cat)&&(flt.store==='all'||f.store===flt.store)}
function filterLabel(flt=currentFilter()){if(flt.cat===DRINK)return flt.store==='all'?'すべての飲み物':`飲み物・${flt.store}`;return flt.store!=='all'?flt.store:flt.cat!=='all'?flt.cat:'すべての購入場所'}
function isEst(f,key){if(f.quality==='estimate')return true;const e=f.est||[];return e.includes(key)||(key!=='price'&&e.includes('nutrition'))}
function estMark(f,key){return isEst(f,key)?'<i class="est-mark">想定</i>':''}
function entries(date=state.date){return state.logs.filter(x=>x.date===date)}
function nutrients(logs){const keys=['kcal','protein','fat','carbs','fiber','salt','price'];const result={unknown:{}};for(const k of keys){result[k]=0;result.unknown[k]=0;for(const item of logs){if(item[k]===null || item[k]===undefined || item[k]===''){result.unknown[k]++;continue}result[k]+=Number(item[k])*(+item.qty||1)}}return result}
function current(){const es=entries();return {eaten:nutrients(es.filter(x=>x.status==='eaten')),planned:nutrients(es.filter(x=>x.status==='planned')),all:nutrients(es),items:es}}
function totalsText(total,key,dec=0){const suffix=total.unknown[key]>0?'＋未確認':' ';return `${fmt(total[key],dec)}${suffix.trim()?` ${suffix.trim()}`:''}`}
function numeric(x){return Number.isFinite(+x)?+x:0}
function foodSnapshot(f,meal,status,day=state.date){return {id:cryptoId(),foodId:f.id,store:f.store,name:f.name,date:day,meal,status,qty:1,quality:f.quality,kcal:f.kcal,protein:f.protein,fat:f.fat,carbs:f.carbs,fiber:f.fiber,salt:f.salt,price:f.price}}
function cryptoId(){return 'l'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('open');clearTimeout(toast._timer);toast._timer=setTimeout(()=>el.classList.remove('open'),2600)}
function progress(k,tot){const target=+state.goals[k]||1;let e=tot.eaten[k]||0,p=tot.planned[k]||0;const key=k==='budget'?'price':k;if(k==='budget'){e=tot.eaten.price;p=tot.planned.price}const val=e+p;const dec=k==='salt'?1:0;const unit=k==='kcal'?'kcal':k==='budget'?'円':'g';const minGoal=k==='protein'||k==='fiber';
 const scale=Math.max(target*1.25,val*1.04);const pct=x=>Math.max(0,Math.min(100,x/scale*100));const over=val>target;const left=target-val;
 const chip=over?(minGoal?`<span class="goal-chip ok">目安達成 ✓</span>`:`<span class="goal-chip over">超過 +${fmt(val-target,dec)}${unit}</span>`):`<span class="goal-chip ${minGoal?'need':'ok'}">${minGoal?'目安まで':'目安内 ✓ 残り'} ${fmt(left,dec)}${unit}</span>`;
 const name={kcal:'エネルギー',protein:'たんぱく質',fat:'脂質',carbs:'炭水化物',fiber:'食物繊維',salt:'食塩相当量',budget:'食費'}[k];
 return `<div class="metric ${over&&!minGoal?'is-over':'is-under'}"><div class="metric-title"><span class="metric-name">${name}</span>${chip}</div><div class="bar target-bar ${over&&!minGoal?'warning':''}"><div class="eaten" style="width:${pct(e)}%"></div><div class="planned" style="width:${Math.max(0,pct(e+p)-pct(e))}%"></div><i class="target-line" style="left:${pct(target)}%" title="1日の摂取目安 ${fmt(target,dec)}${unit}"></i></div><div class="metric-foot"><span><b>${fmt(val,dec)}</b>${unit}（摂取 ${fmt(e,dec)} ＋予定 ${fmt(p,dec)}）${tot.all.unknown[key]?' · 一部不明':''}</span><span class="target-label">目安 ${fmt(target,dec)}${unit}</span></div></div>`}
function badge(f){const label=f.quality==='official'?'公式情報':f.quality==='custom'?(isEst(f,'kcal')?'自己登録・想定':'自己登録'):'想定';return `<span class="tag ${f.quality==='official'?'':'estimated'}">${label}</span>`}
function summaryStats(){const t=current();const c=t.all;const g=state.goals;return `<div class="card-grid"><div class="panel stat"><div class="icon">◉</div><div class="label">摂取済みカロリー</div><div class="num ${c.kcal>g.kcal?'warn':''}">${fmt(t.eaten.kcal)}<span class="unit">kcal</span></div><div class="sub">予定 ${fmt(t.planned.kcal)} / 目標 ${fmt(g.kcal)}</div></div><div class="panel stat"><div class="icon">♢</div><div class="label">たんぱく質</div><div class="num">${fmt(c.protein,1)}<span class="unit">g</span></div><div class="sub">摂取＋予定 / 目標 ${g.protein}g</div></div><div class="panel stat"><div class="icon">♧</div><div class="label">塩分</div><div class="num ${c.salt>g.salt?'warn':''}">${fmt(c.salt,1)}<span class="unit">g</span></div><div class="sub">摂取＋予定 / 目標上限 ${g.salt}g</div></div><div class="panel stat"><div class="icon">¥</div><div class="label">食費の残り（予定込み）</div><div class="num ${g.budget-c.price<0?'warn':'good'}">${money(g.budget-c.price)}</div><div class="sub">確定・予定 ${money(c.price)} / 上限 ${money(g.budget)}${c.unknown.price?' · 一部未確認':''}</div></div></div>`}
function dateChooser(){return `<div class="date-controls"><button class="btn btn-sm" data-action="prev" title="前の日">‹</button><input type="date" id="dayInput" value="${state.date}" aria-label="対象日"><button class="btn btn-sm" data-action="next" title="次の日">›</button><button class="btn btn-sm btn-soft" data-action="todayDate">今日</button></div>`}
function today(){const t=current();let missing=0;const mealcards=MEALS.map(m=>{const items=t.items.filter(x=>x.meal===m);const sums=nutrients(items);missing+=items.filter(x=>x.price==null).length;return `<div class="panel meal-card"><div class="meal-head"><div class="meal-ico">${MEAL_ICON[m]}</div><div><div class="meal-name">${MEAL_LABEL[m]}</div><div class="meal-meta">${fmt(sums.kcal)} kcal ・ ${money(sums.price)}${sums.unknown.price?'＋未確認':''}</div></div></div><div class="meal-body">${items.length?items.map(x=>`<div class="log-swipe" data-id="${x.id}"><div class="swipe-bg swipe-del">削除</div><div class="swipe-bg swipe-eat">${x.status==='eaten'?'予定に戻す':'食べた'}</div><div class="log-item" data-id="${x.id}"><div class="flex-full"><div class="log-name">${safe(x.name)} <span class="log-amount">${amountLabel(x)}</span></div><div class="log-sub">${safe(x.store)} · ${fmt(x.kcal*x.qty)} kcal <span class="tiny-tag ${x.status}">${x.status==='eaten'?'食べた':'予定'}</span></div></div><div class="log-acts"><button class="icon-btn" data-action="qtyDown" data-id="${x.id}" title="数量を減らす">−</button><button class="icon-btn" data-action="qtyUp" data-id="${x.id}" title="数量を増やす">＋</button></div></div></div>`).join(''):'<div class="empty-meal">まだ食事の記録がありません</div>'}</div><div class="meal-bottom"><button class="btn btn-sm btn-soft" data-action="recommendMeal" data-meal="${m}">✦ 提案を見る</button><button class="btn btn-sm" data-action="pickMeal" data-meal="${m}">＋ 登録</button></div></div>`}).join('');
const noted=[];if(t.all.salt>state.goals.salt)noted.push('予定を含む塩分が目標上限を超えています。調味料や汁物の量にも注意してください。');if(t.all.kcal>state.goals.kcal)noted.push('予定を含むカロリーが設定目標を超えています。運動量や空腹感に合わせて適正量を見直してください。');if(t.all.price>state.goals.budget)noted.push('現在の食費は予算を超えています。購入前に調整しましょう。');if(missing)noted.push('価格が未確認の商品があります。食費合計は一部を含みません。');
const shopping=t.items.filter(x=>x.status==='planned');const shopmap={};for(const x of shopping)(shopmap[x.store]??=[]).push(x);
return `<div class="hello"><div><div class="eyebrow">${PERIOD_INFO[periodByHour(jstHour())].eyebrow}</div><h1>${readable(state.date)}の食事</h1><p class="period-greeting">${PERIOD_INFO[periodByHour(jstHour())].greet}</p><p>「食べた」と「予定」を分けて記録し、次の食事を選べます。</p></div>${dateChooser()}</div>${healthContextRibbon()}${summaryStats()}<div class="two-col"><section class="panel pad"><div class="section-heading"><h2>栄養バランス</h2><span class="small-note legend"><i class="lg eaten"></i>摂取 <i class="lg planned"></i>予定 <i class="lg line"></i>1日の目安</span></div><div class="metrics">${['kcal','protein','fat','carbs','fiber','salt','budget'].map(k=>progress(k,t)).join('')}</div><p class="small-note mt">一部の商品で食物繊維などが未公表のため、表示合計は把握できた値の合算です。未確認を0gと解釈しないでください。</p></section><section class="panel pad"><div class="section-heading"><h2>今日のアドバイス</h2><span class="tag">栄養・予算から算出</span></div><div class="stack">${noted.map(v=>`<div class="notice orange">${safe(v)}</div>`).join('')}${t.items.length===0?'<div class="notice"><b>まず朝食・昼食・夕食を作成</b>「1日分を自動で仮登録」からメニューを組み立てられます。</div>':''}${healthPriorities().length?healthPriorities().slice(0,2).map(x=>`<div class="notice orange"><b>${safe(x.name)}の記録を考慮</b>${safe(x.text)}</div>`).join(''):'<div class="notice">健診情報を登録すると、記録した数値に合わせて候補の優先度を調整できます。</div>'}<div class="between wrap"><button class="btn btn-primary" data-action="autoDay">✦ 1日分を自動で仮登録</button><button class="btn" data-page="recommend">店舗別提案へ →</button></div><span class="small-note">自動作成はルールベース。未入力の食事だけ追加し、自炊中心／昼は選択店舗を優先します。</span></div></section></div><div class="section-heading"><h2>食事のタイムライン</h2><span class="small-note">← スワイプで削除 · → スワイプで「食べた」に</span></div><div class="meal-grid">${mealcards}</div><section class="panel pad"><div class="section-heading"><h2>購入予定リスト</h2><div class="hello-actions"><button class="btn btn-sm" data-action="shareShopping">↗ 共有</button><button class="btn btn-sm" data-action="exportCalendar">▦ カレンダー</button><button class="btn btn-sm" data-action="copyShopping">コピー</button></div></div>${yesterdayBlock()}${shopping.length?Object.entries(shopmap).map(([s,rows])=>`<div class="between" style="margin:8px 0"><div><b>${safe(s)}</b><div class="small-note">${rows.map(x=>safe(x.name)+' '+amountLabel(x)).join(' / ')}</div></div><div class="bold">${money(nutrients(rows).price)}${nutrients(rows).unknown.price?'＋未確認':''}</div></div>`).join(''):'<div class="small-note">「予定」として登録した商品がここに並びます。</div>'}</section>`}
function storeSelector(){const cats=usedCategories();const hidden=state.storeRowHidden&&state.cat!=='all';const row1=`<div class="store-row cat-row">${[['all','◎'],...cats].map(([c,ic])=>{const on=state.cat===c;const sel=on&&hidden&&state.store!=='all'?`<em class="cat-sel">${safe(state.store)}</em>`:'';return `<button class="chip cat-chip ${on?'active':''} ${on&&hidden?'collapsed':''}" data-cat="${attr(c)}" ${on&&c!=='all'?`aria-expanded="${hidden?'false':'true'}"`:''}><span aria-hidden="true">${ic}</span>${c==='all'?'すべて':safe(c)}${sel}</button>`}).join('')}</div>`;if(hidden)return row1;
 if(state.cat==='all')return row1;if(state.cat===DRINK)return row1+`<div class="store-row sub-row" aria-label="飲み物の購入場所">${['all',...drinkPlaces()].map(s=>`<button class="chip ${state.store===s?'active':''}" data-store="${attr(s)}">${s==='all'?'すべての飲み物':safe(s)}</button>`).join('')}</div>`;const list=storesIn(state.cat);if(list.length<2)return row1;const counts=storeCounts();const chip=s=>`<button class="chip ${state.store===s?'active':''}" data-store="${attr(s)}">${s==='all'?`すべての${safe(state.cat)}`:safe(s)}${s!=='all'&&counts.get(s)?`<small>${counts.get(s)}</small>`:''}</button>`;
 const groups=[];for(const s of list){const g=STORE_GROUP[s]||'';const last=groups[groups.length-1];if(last&&last[0]===g)last[1].push(s);else groups.push([g,[s]])}
 const labeled=groups.filter(g=>g[0]).length>1;
 return row1+`<div class="store-row sub-row ${labeled?'grouped':''}" aria-label="${attr(state.cat)}の店舗">${chip('all')}${labeled?groups.map(([g,l])=>`<div class="store-group"><span class="group-label">${safe(g||'その他')}</span>${l.map(chip).join('')}</div>`).join(''):list.map(chip).join('')}</div>`}
function foodKind(f){if(f.kind&&f.kind!=='food')return f.kind;const n=f.name||'';if(/おにぎり|むすび|ご飯|ライス/.test(n))return 'rice';if(/弁当|丼|定食|カレー|麺|うどん|そば|パスタ|スパゲッティ|焼きそば|ラーメン/.test(n))return 'meal';if(/サンド|バーガー|パン|マフィン/.test(n))return 'main';if(/サラダ|野菜/.test(n))return 'vegetable';if(/汁|スープ/.test(n))return 'soup';if(/茶|コーヒー|ジュース|牛乳|ラテ|ドリンク|水/.test(n))return 'drink';if(f.store==='自炊・スーパー')return f.kind||'food';if(['松屋','すき家'].includes(f.store))return 'meal';if(f.store==='マクドナルド')return 'main';if(f.store==='ローソン')return 'protein';if(f.name.includes('ロール'))return 'main';if(f.name.includes('ランチ'))return 'meal';if(f.name.includes('おむすび')||f.name.includes('むすび'))return 'rice';return f.kind||'food'}
function validCombo(items){const kinds=items.map(foodKind);const c=k=>kinds.filter(x=>x===k).length;if(c('soup')>1||c('side')>1||c('sweet')>1)return false;if(c('main')&&c('rice'))return false;if(items.length>1&&kinds.every(k=>['drink','sweet','snack','fruit'].includes(k)))return false;if(kinds.filter(k=>k==='meal').length>0&&items.length>1)return false;if(kinds.filter(k=>k==='main').length>1)return false;if(kinds.filter(k=>k==='rice').length>1)return false;if(kinds.filter(k=>k==='protein').length>1)return false;if(kinds.filter(k=>k==='drink').length>1)return false;if(kinds.filter(k=>k==='fruit').length>1)return false;if(kinds.filter(k=>k==='snack').length>1)return false;if(kinds.filter(k=>k==='vegetable').length>2)return false;return true}
function combine(items){let r={kcal:0,protein:0,fat:0,carbs:0,salt:0,fiber:0,price:0,unknownFiber:0};for(const x of items){for(const k of ['kcal','protein','fat','carbs','salt','price','fiber']){if(x[k]===null||x[k]===undefined){if(k==='fiber')r.unknownFiber++;continue}r[k]+=x[k]}}return r}
function candidates(day,meal,flt=currentFilter()){if(typeof flt==='string')flt={cat:flt==='all'?'all':storeCat(flt),store:flt};const isDrink=meal==='drink';const foods0=foods().filter(f=>matchesFilter(f,flt) && (f.time==='any'||f.time===meal||isDrink) && f.price!=null && (!isDrink||foodKind(f)==='drink'));const cur=nutrients(state.logs.filter(x=>x.date===day));const mealUsed=nutrients(state.logs.filter(x=>x.date===day&&x.meal===meal));const budgetRemaining=Math.max(0,state.goals.budget-cur.price);const kcRemaining=Math.max(0,state.goals.kcal-cur.kcal);const factors={breakfast:.27,lunch:.36,dinner:.33,snack:.10,drink:.05};const aim=Math.max(80,Math.min(state.goals.kcal*factors[meal]-mealUsed.kcal,kcRemaining));const proteinAim=Math.max(9,Math.min(42,(state.goals.protein-cur.protein)*.43));const fiberAim=Math.max(1,Math.min(9,(state.goals.fiber-cur.fiber)*.40));let result=[];function evaluate(items){if(!validCombo(items))return null;if(isDrink){if(items.length>1)return null;const v=combine(items);if(v.price>budgetRemaining+0.01)return null;let score=100-v.kcal*0.12-v.salt*8-v.carbs*0.15+Math.min(12,v.protein*1.2)+Math.min(6,v.fiber*2)-v.price/Math.max(150,state.goals.budget)*12-entries(day).filter(x=>x.foodId===items[0].id).length*8;result.push({items,v,score,reason:drinkReason(v)});return score}const v=combine(items);if(v.price>budgetRemaining+0.01 || v.kcal>kcRemaining*1.2+90 ||v.salt>Math.max(1.5,(state.goals.salt-cur.salt)*1.2)&& v.salt>2.2)return null;let score=100;score-=Math.abs(v.kcal-aim)/Math.max(aim,250)*43;score-=Math.max(0,proteinAim-v.protein)*1.25;score-=Math.max(0,v.fat-22)*1.2;score-=Math.max(0,v.salt-1.7)*8;score-=Math.max(0,v.salt-(state.goals.salt-cur.salt))*19;if(state.profile.systolic>=130||state.profile.diastolic>=85)score-=Math.max(0,v.salt-1.35)*5;if(state.profile.tg>=150){score+=Math.min(5,v.fiber*.65);score-=Math.max(0,v.carbs-aim*.60/4)*.2;}score-=v.price/Math.max(150,state.goals.budget)*9;score+=Math.min(10,v.fiber/Math.max(1,fiberAim)*8);score-=v.unknownFiber*2.2;if(items.some(f=>f.quality==='estimate'))score-=2;if(items.some(f=>f.price_type==='from'))score-=1;const cnt=entries(day).filter(x=>items.some(f=>f.id===x.foodId)).length;score-=cnt*8;if(items.length>=2&&v.kcal>=aim*.65&&v.protein>=proteinAim*.65)score+=5;if(items.length===3&&v.kcal<aim*.35)score-=14;result.push({items,v,score,store:curStore,reason:reasonFor(v,aim,proteinAim,budgetRemaining)});return score}
const byStore={};const shared=foods0.filter(f=>f.places);for(const f of foods0){if(f.places&&!isDrink)continue;(byStore[f.store]??=[]).push(f)}if(!isDrink){const real=[...new Set([...stores(),...state.custom.map(f=>f.store)])].filter(st=>!['メーカー','まとめ'].includes(storeCat(st))&&(flt.store==='all'||flt.store===st)&&(flt.cat==='all'||flt.cat===DRINK||storeCat(st)===flt.cat));for(const f of shared)for(const st of real)if(soldAt(f,st)){const list=(byStore[st]??=[]);if(!list.includes(f))list.push(f)}}
let curStore=null;for(const [groupStore,list] of Object.entries(byStore)){curStore=groupStore;if(isDrink){for(const f of list)evaluate([f]);continue}const singles=[];for(const f of list){const before=result.length;const sc=evaluate([f]);if(result.length>before)result.pop();singles.push({f,sc:sc==null?-1e9:sc})}
 singles.sort((a,b)=>b.sc-a.sc);const pick=[...singles.slice(0,13).map(x=>x.f)];const add=arr=>{for(const f of arr)if(!pick.includes(f)&&pick.length<20)pick.push(f)};
 add(list.slice().sort((a,b)=>b.protein-a.protein).slice(0,4));add(list.filter(f=>['vegetable','soup'].includes(foodKind(f))).sort((a,b)=>(b.fiber||0)-(a.fiber||0)).slice(0,4));add(list.filter(f=>['rice','main','meal'].includes(foodKind(f))).slice(0,3));
 for(let i=0;i<pick.length;i++){evaluate([pick[i]]);if(isDrink)continue;for(let j=i+1;j<pick.length;j++){evaluate([pick[i],pick[j]]);for(let k=j+1;k<pick.length;k++)evaluate([pick[i],pick[j],pick[k]])}}}
result.sort((a,b)=>b.score-a.score);const seen=new Set(),perStore={},out=[];const multi=Object.keys(byStore).length>1;
for(const r of result){const key=r.items.map(f=>f.id).sort().join('|');if(seen.has(key))continue;seen.add(key);const st=r.store||r.items[0].store;if(multi&&(perStore[st]||0)>=3)continue;perStore[st]=(perStore[st]||0)+1;out.push(r);if(out.length>=20)break}return out}
function drinkReason(v){const r=[];if(v.kcal<=5)r.push('カロリーほぼゼロ');else if(v.carbs>=20)r.push('糖分が多めなので量に注意');if(v.protein>=5)r.push('たんぱく質を補える');if(v.fiber>=2)r.push('食物繊維入り');if(v.price<=80)r.push('価格が手頃');return (r.length?r:['飲み物として選定']).join(' · ')}
function reasonFor(v,aim,proteinAim,budget){let r=[];if(v.protein>=proteinAim)r.push('たんぱく質を確保');if(v.fiber>=5)r.push('食物繊維が比較的豊富');if(v.salt<=1.5)r.push(state.profile.systolic>=130?'血圧の記録を踏まえ塩分控えめ':'塩分が比較的少なめ');if(state.profile.tg>=150&&v.fiber>=4)r.push('中性脂肪の記録を踏まえ繊維を優先');if(v.kcal<aim*.6)r.push('食事としてはエネルギーが少なめ');if(v.price<=budget*.5)r.push('予算に余裕');return (r.length?r:['現在の残り目標と予算から選定']).slice(0,3).join(' · ')}
function recommendation(){let cur=current(),result=candidates(state.date,state.meal,currentFilter());let hasUnknown=cur.all.unknown.price>0;
return `<div class="hello"><div><div class="eyebrow">SMART STORE RECOMMENDER</div><h1>今、何を買うべき？</h1><p>今日食べたものと予定、残りの栄養・予算から購入候補を計算します。</p></div>${dateChooser()}</div><div class="panel pad mb"><div class="section-heading"><h2>購入場所を選択</h2><span class="small-note">同じ店舗の商品だけを組み合わせます</span></div>${storeSelector()}<div class="divider"></div><div class="filters"><div class="field"><label>おすすめする食事</label><select id="mealSelect">${MEALS.map(m=>`<option value="${m}" ${state.meal===m?'selected':''}>${MEAL_LABEL[m]}</option>`).join('')}</select></div><div class="field"><label>残りの予算（予定を含む）</label><input value="${money(Math.max(0,state.goals.budget-cur.all.price))}${hasUnknown?'＋未確認商品あり':''}" disabled></div><button class="btn btn-dark" data-page="catalog">商品データを見る →</button></div></div>${healthContextRibbon()}<div class="section-heading"><h2>おすすめの購入候補</h2><span class="small-note">${result.length}パターン計算 · 点数は独自の適合度です</span></div>${result.length?`<div class="reco-top">${result.slice(0,6).map((r,i)=>`<div class="panel reco-card"><span class="reco-kicker">${i===0?'BEST MATCH / 最優先':`OPTION ${i+1}`} · ${safe(r.store&&!['メーカー','まとめ'].includes(storeCat(r.store))?r.store:r.items[0].places?r.items[0].places.join('・'):r.items[0].store)}</span><h3>${r.items.length===1?safe(r.items[0].name):`${r.items.length}商品の組み合わせ`}</h3><div class="reco-items">${r.items.map(f=>safe(f.name)).join(' ＋ ')}</div><div class="reco-stats"><span>${fmt(r.v.kcal)} kcal</span><span>P ${fmt(r.v.protein,1)}g</span><span>脂質 ${fmt(r.v.fat,1)}g</span><span>塩分 ${fmt(r.v.salt,1)}g</span><span>食物繊維 ${fmt(r.v.fiber,1)}g${r.v.unknownFiber?'＋不明':''}</span></div><div class="reco-reason">✦ ${safe(r.reason)}${r.items.some(f=>isEst(f,'kcal')||isEst(f,'price'))?' · 想定値を含みます':''}</div><div class="reco-footer"><strong>${r.items.some(f=>isEst(f,'price'))?'約':''}${money(r.v.price)}<small> / 目安</small></strong><button class="btn btn-primary btn-sm" data-action="chooseReco" data-idx="${i}">予定に追加 ＋</button></div></div>`).join('')}</div><p class="small-note">価格未確認商品は自動推薦から除外しています。「〜円」価格は最低表示価格のため、店舗で高くなる場合があります。1食だけで必要栄養素を満たすとは限りません。</p>`:'<div class="panel empty-state"><div class="emoji">◌</div><b>この条件に合う商品がありません</b><p>店舗・時間帯を変更するか、目標予算を見直してください。価格未登録の商品は推薦対象外です。</p></div>'}<div class="panel pad mt"><div class="section-heading"><h2>計算に使用した今日の残り目標</h2><small>摂取＋予定を差し引いた量</small></div><div class="pill-stats">${[['kcal','kcal'],['protein','g'],['fiber','g'],['salt','g'],['budget','円']].map(([k,u])=>`<span>${{kcal:'エネルギー',protein:'たんぱく質',fiber:'食物繊維',salt:'塩分の残枠',budget:'予算の残り'}[k]}：${fmt(Math.max(0,state.goals[k]-cur.all[k==='budget'?'price':k]),k==='salt'?1:0)}${u}</span>`).join('')}</div></div>`}
const phoneQuery='(max-width:790px),(pointer:coarse) and (max-height:520px)';function isPhone(){try{return matchMedia(phoneQuery).matches}catch{return false}}
