function saveHealthReview(form){const d=new FormData(form);let updated=0;for(const meta of PROFILE_FIELDS){const raw=d.get(meta[0]);if(raw===null||String(raw).trim()==='')continue;state.profile[meta[0]]=validProfileNumeric(raw,meta);updated++;}if(d.get('birth')){state.profile.birth=String(d.get('birth'));updated++}if(d.get('age')!==''){state.profile.age=String(d.get('age'));updated++}if(['male','female'].includes(d.get('sex'))){state.profile.sex=String(d.get('sex'));updated++}if(!updated){toast('保存する数値がありません');return}state.profile.measuredAt=String(d.get('measuredAt')||dateStr());captureMeasurement('screen_capture');const applied=updateGoalsFromProfile();persist();closeModal();switchPage('profile');toast(`${updated}項目を登録${applied?'し、栄養目標を更新':''}しました`)}

