let onlineResults=[];
const OFF_FIELDS='code,product_name,product_name_ja,brands,quantity,serving_quantity,serving_size,nutriments,image_front_small_url';
function offFetch(u,ms=12000){const c=new AbortController();const t=setTimeout(()=>c.abort(),ms);return fetch(u,{signal:c.signal,headers:{Accept:'application/json'}}).finally(()=>clearTimeout(t))}
function offProduct(p){const n=p.nutriments||{};const name=String(p.product_name_ja||p.product_name||'').trim();if(!name)return null;const qty=String(p.quantity||'');const m=qty.match(/([0-9]+(?:\.[0-9]+)?)\s*(ml|mL|l|L|g|kg)/);let amount=m?+m[1]*(/^(l|L|kg)$/.test(m[2])?1000:1):null;const unit=m?(/l/i.test(m[2])?'ml':'g'):'g';
 let basis=amount&&amount<=700?amount:Number(p.serving_quantity)||(amount?200:100);const per=(k,alt)=>{const v=n[k+'_100g'];return v==null||v===''?alt:+v};
 const kcal=per('energy-kcal',n['energy_100g']!=null?+n['energy_100g']/4.184:null);if(kcal==null)return {name,brand:p.brands||'',code:p.code,amount,unit,basis,missing:true};
 const k=basis/100;const r=x=>x==null?null:+(x*k).toFixed(1);const salt=per('salt',n['sodium_100g']!=null?+n['sodium_100g']*2.54:null);
 return {name,brand:p.brands||'',code:p.code,amount,unit,basis,kcal:Math.round(kcal*k),protein:r(per('proteins',0)),fat:r(per('fat',0)),carbs:r(per('carbohydrates',0)),salt:r(salt??0),fiber:r(per('fiber',null))}}
async function searchOnline(code){const box=document.getElementById('onlineResults');const q=String(document.getElementById('onlineQuery')?.value||document.querySelector('#foodForm [name="name"]')?.value||'').trim();if(!box)return;if(!code&&!q){box.innerHTML='<div class="small-note ocr-error">商品名を入力してください。</div>';return}
 box.innerHTML='<div class="small-note">検索中…</div>';
 try{let list=[];if(code){const r=await offFetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json?fields=${OFF_FIELDS}`);const d=await r.json();if(d?.product)list=[d.product]}
  else{const r=await offFetch(`https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(q)}&search_simple=1&action=process&json=1&page_size=12&fields=${OFF_FIELDS}`);const d=await r.json();list=d?.products||[]}
  onlineResults=list.map(offProduct).filter(Boolean).slice(0,8);
  if(!onlineResults.length){box.innerHTML=`<div class="small-note">${code?'バーコードの商品が見つかりませんでした。':'見つかりませんでした。'}商品名を変えて検索するか、「内容物から栄養を推定」で想定値を入力できます。</div>`;return}
  box.innerHTML=onlineResults.map((x,i)=>`<button type="button" class="online-item" data-action="pickOnline" data-idx="${i}"><span><b>${safe(x.name)}</b><small>${safe(x.brand)}${x.amount?` · ${fmt(x.amount)}${x.unit}`:''}</small></span><span class="online-kcal">${x.missing?'栄養未登録':`${fmt(x.kcal)}kcal<small>/${fmt(x.basis)}${x.unit}</small>`}</span></button>`).join('')+'<div class="small-note">登録は有志による公開データです。包装の表示と照らして確認してください。</div>'}
 catch{box.innerHTML='<div class="small-note ocr-error">検索できませんでした（通信状況をご確認ください）。「内容物から栄養を推定」も利用できます。</div>'}}
function pickOnline(i){const x=onlineResults[i];const form=document.getElementById('foodForm');if(!x||!form)return;const label=x.amount&&x.basis!==x.amount?`${x.name}（${fmt(x.basis)}${x.unit}分）`:x.name;setField(form,'name',(x.brand&&!x.name.includes(x.brand.split(',')[0])?x.brand.split(',')[0]+' ':'')+label);setField(form,'weight',x.basis);
 form.dataset.source=x.code?`https://world.openfoodfacts.org/product/${x.code}`:'';if(x.code)setField(form,'source',form.dataset.source);
 if(x.missing){estimateFood(true);foodStatus('この商品は栄養成分が未登録のため、内容物から「想定」値を入力しました。');return}
 for(const k of ['kcal','protein','fat','carbs','salt'])setField(form,k,x[k]);if(x.fiber!=null)setField(form,'fiber',x.fiber);form.elements.estimated.checked=false;setField(form,'note',`Open Food Facts の掲載値（${fmt(x.basis)}${x.unit}あたり）`);
 document.querySelectorAll('.online-item').forEach((b,j)=>b.classList.toggle('active',j===i));toast('検索結果の栄養成分を入力しました')}
