(()=>{let drag=null;const TH=90;
 document.addEventListener('pointerdown',e=>{const item=e.target.closest('.log-item');if(!item||e.target.closest('button'))return;drag={item,wrap:item.closest('.log-swipe'),x:e.clientX,y:e.clientY,dx:0,on:false,pid:e.pointerId}});
 document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pid)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.on){if(Math.abs(dx)<10)return;if(Math.abs(dy)>Math.abs(dx)){drag=null;return}drag.on=true;try{drag.item.setPointerCapture(e.pointerId)}catch{}drag.item.classList.add('dragging')}drag.dx=dx;drag.item.style.transform=`translateX(${dx}px)`;drag.wrap.classList.toggle('to-del',dx<-TH);drag.wrap.classList.toggle('to-eat',dx>TH);drag.wrap.dataset.dir=dx<0?'left':'right'});
 const end=e=>{if(!drag)return;const {item,wrap,dx,on}=drag;drag=null;if(!on)return;item.classList.remove('dragging');const id=wrap.dataset.id;
  if(dx<-TH){item.style.transform='translateX(-110%)';setTimeout(()=>document.dispatchEvent(new CustomEvent('nutripath:swipe',{detail:{id,dir:'left'}})),160)}
  else if(dx>TH){item.style.transform='';document.dispatchEvent(new CustomEvent('nutripath:swipe',{detail:{id,dir:'right'}}))}
  else{item.style.transform='';wrap.classList.remove('to-del','to-eat')}};
 document.addEventListener('pointerup',end);document.addEventListener('pointercancel',end);
})();
